# Vertragszeitraum, Beantragung, Einstieg, Maßnahmenwechsel, Übernahme und Ausstieg
# (Maßnahmenblatt Kap. 3.1, 5; Allgemeine Bedingungen 5.8, 5.9, 6, 6.2, 6.3, 7; SRL 1.7, 1.10.5).
package oepul.o6_4

contract_periods := data.o6_4.contract_periods

# O6_4-CONTRACT-001: Vertragszeitraum je Vertragsbeginn (mindestens 4 Jahre, bis 31.12.2028).
contract_period_for_start(start_date) := r if {
	some r in contract_periods.rows
	r.start_date == start_date
}

# O6_4-APP-002: letzter Einstieg mit Förderjahr 2025.
entry_year_allowed(start_year) if {
	some r in contract_periods.rows
	r.start_year == start_year
	start_year <= contract_periods.last_entry_year
}

# O6_4-APP-001 / GEN-APP-001: Beantragung im Maßnahmenantrag bis spätestens 31.12. vor Vertragsbeginn.
application_timely(application_date, start_date) if {
	date_ns(application_date) < date_ns(start_date)
	date_parts(start_date)[1] == 1
	date_parts(start_date)[2] == 1
	date_parts(application_date)[0] == date_parts(start_date)[0] - 1
}

application_timely(application_date, start_date) if {
	date_ns(application_date) < date_ns(start_date)
	date_parts(start_date)[1] == 1
	date_parts(start_date)[2] == 1
	date_parts(application_date)[0] < date_parts(start_date)[0] - 1
}

default application_status := {"contract_valid": false, "reasons": ["no_measure_record"]}

application_status := {"contract_valid": count(application_problems) == 0, "reasons": sort([x | some x in application_problems])} if {
	measure_record
}

application_problems contains "O6_4-APP-001" if {
	not application_timely(measure_record.measure_application_date, measure_record.contract_start_date)
}

application_problems contains "O6_4-APP-002" if {
	not entry_year_allowed(date_parts(measure_record.contract_start_date)[0])
}

application_problems contains "GEN-APPL-001" if not applicant_eligible

application_problems contains "GEN-MIN-001" if not minimum_farm_size_met

contract_end_date := contract_periods.contract_end_date

# GEN-DUR-001: Verpflichtungsdauer umfasst das gesamte Kalenderjahr.
commitment_period(yr) := {"from": sprintf("%d-01-01", [yr]), "to": sprintf("%d-12-31", [yr])}

# O6_4-APP-003 / GEN-SWITCH-001: Umstieg in Naturschutz (o6_18) oder Ergebnisorientierte Bewirtschaftung (o6_19)
# mit einzelnen oder allen Flächen bis spätestens 31.12.2025, ohne Rückzahlungsverpflichtung.
switch_allowed(target, switch_date) if {
	some r in params.measure_switch.rows
	r.from == measure_id
	target in r.to
	date_ns(switch_date) <= date_ns(params.measure_switch.latest_switch_date)
}

# GEN-TAKEOVER-001: Maßnahmenübernahme bis 15.04. (2023 und 2028: 17.04.) des Übernahmejahres,
# Ausweitung auf andere Flächen höchstens um 50 %.
takeover_deadline(yr) := sprintf("%d-04-%02d", [yr, params.takeover.deadline_day_in_exception_years]) if {
	yr in {y | some y in params.takeover.deadline_day_exception_years}
} else := sprintf("%d-04-%02d", [yr, params.takeover.deadline_day])

takeover_allowed(takeover_date, expansion_share) if {
	yr := date_parts(takeover_date)[0]
	date_ns(takeover_date) <= date_ns(takeover_deadline(yr))
	expansion_share <= params.takeover.max_expansion_share
}

# GEN-EXIT-001: Ausstieg aus mehrjähriger Maßnahme vor Ende des Vertragszeitraumes → Rückforderung
# bereits gewährter Maßnahmenprämien (ausgenommen Maßnahmenwechsel, Verlust der Verfügungsgewalt,
# höhere Gewalt/dauerhafte Umstände, Revisionsklausel).
repayment_exemption_reasons := {
	"measure_switch_to_higher_value",
	"loss_of_control_over_area",
	"force_majeure_or_permanent_circumstances",
	"revision_clause_refusal",
}

early_exit_repayment_required if {
	exit_date := measure_record.exit_date
	exit_date != null
	date_ns(exit_date) < date_ns(contract_end_date)
	not object.get(measure_record, "exit_reason", null) in repayment_exemption_reasons
}

# GEN-EXIT-002: Abmeldung zwischen 1.1. und 31.12. → Maßnahme im betroffenen Förderjahr nicht mehr gültig.
measure_valid_in_year(yr) if {
	measure_record
	not deregistered_in_year(yr)
}

deregistered_in_year(yr) if date_parts(measure_record.exit_date)[0] == yr

# SRL-NONAPP-001: Nichtbeantragung ab dem 2. Verpflichtungsjahr – Verpflichtung bleibt, keine Zahlung;
# nicht binnen 1 Jahr nachgeholt → Verpflichtung endet, bisher gewährte Prämien sind zurückzuzahlen.
non_application_consequence(submitted_late_within_one_year) := "commitment_remains_no_payment" if {
	submitted_late_within_one_year == true
} else := "commitment_ends_full_repayment"

# Teilnahmefähige Flächen (Maßnahmenblatt Kap. 3.2, SRL 2.4 Zugangsvoraussetzungen).
package oepul.o6_4

# O6_4-ELIG-001: Teilnahme ausschließlich mit Bergmahdflächen (Schlagnutzungsart „Bergmähder").
eligibility_failure contains [pid, "O6_4-ELIG-001"] if {
	some pid, p in enrolled_parcels
	not object.get(p, ["mountain_meadow", "declared_as_mountain_meadow"], false) == true
}

# O6_4-ELIG-002: mehr als die Hälfte der Schlagfläche über 1.200 m Seehöhe.
eligibility_failure contains [pid, "O6_4-ELIG-002"] if {
	some pid, p in enrolled_parcels
	not majority_above_1200m(p)
}

majority_above_1200m(p) if p.mountain_meadow.share_above_1200m_percent > 50

# O6_4-ELIG-003: extensive Mähfläche über der örtlichen Dauersiedlungsgrenze.
eligibility_failure contains [pid, "O6_4-ELIG-003"] if {
	some pid, p in enrolled_parcels
	not object.get(p, ["mountain_meadow", "above_local_permanent_settlement_limit"], false) == true
}

# O6_4-ELIG-004: über der Seehöhe des Heimbetriebes; bei Almbetrieben auch unter der Almbetriebsstätte zulässig.
eligibility_failure contains [pid, "O6_4-ELIG-004"] if {
	some pid, p in enrolled_parcels
	not above_home_farm_or_alpine_exception(p)
}

above_home_farm_or_alpine_exception(p) if {
	p.mountain_meadow.parcel_altitude_m > participation.home_farm_altitude_m
}

above_home_farm_or_alpine_exception(_) if participation.is_alpine_farm_operation == true

# GEN-LOC-001: geförderte Flächen müssen in Österreich liegen.
eligibility_failure contains [pid, "GEN-LOC-001"] if {
	some pid, p in enrolled_parcels
	object.get(p, "located_in_austria", true) == false
}

# GEN-ELIG-002: nicht förderfähige Flächenkategorien (geschlossene Liste in data).
non_eligible_category_keys := {r.key | some r in params.non_eligible_area_categories.rows}

eligibility_failure contains [pid, "GEN-ELIG-002"] if {
	some pid, p in enrolled_parcels
	some k in object.get(p, "non_eligible_categories", [])
	k in non_eligible_category_keys
	k != "national_park"
}

# O6_4-ELIG-005: Bergmähder grenzen in der Regel nicht an Heimbetriebsflächen – nur Prüfhinweis.
advisory contains {"rule_id": "O6_4-ELIG-005", "parcel_id": pid, "message": "Bergmahdfläche grenzt unmittelbar an Heimbetriebsflächen – Einstufung als Bergmahd prüfen"} if {
	some pid, p in enrolled_parcels
	p.mountain_meadow.adjacent_to_home_farm_areas == true
}

parcel_failures(pid) := {rid | some [id, rid] in eligibility_failure; id == pid}

parcel_eligible(pid) if {
	enrolled_parcels[pid]
	count(parcel_failures(pid)) == 0
}

eligibility[pid] := {
	"eligible": count(parcel_failures(pid)) == 0,
	"failed_rules": sort([r | some r in parcel_failures(pid)]),
} if {
	some pid, _ in enrolled_parcels
}

# Allgemeine Teilnahmebedingungen, soweit für o6_4 maßgeblich
# (Allgemeine Bedingungen 5.2, 5.3, 7.1, 7.2, 8.2; SRL 1.4, 1.6, 1.7.2, 1.12).
package oepul.o6_4

# GEN-APPL-001: förderwerbende Personen; Gebietskörperschaften (Beteiligung > 25 %) für o6_4 ausgeschlossen;
# aktive Landwirtin/aktiver Landwirt, Bewirtschaftung im eigenen Namen und auf eigene Rechnung.
applicant_eligible if {
	participation.applicant_type in {t | some t in params.applicants.eligible_applicant_types}
	object.get(participation, "public_body_share_percent", 0) <= params.applicants.max_public_body_share_percent
	participation.is_active_farmer == true
	participation.manages_in_own_name_and_account == true
}

# GEN-MIN-001/-002: Betriebsmindestgröße nur im ersten ÖPUL-Teilnahmejahr.
minimum_farm_size_met if not first_participation_year

minimum_farm_size_met if {
	first_participation_year
	object.get(participation, "protected_cultivation_area_ha", 0) >= params.minimum_farm_size_first_year.protected_cultivation_min_ha
}

minimum_farm_size_met if {
	first_participation_year
	object.get(input.land, "total_area_ha", 0) >= params.minimum_farm_size_first_year.agricultural_area_min_ha
}

first_participation_year if participation.first_oepul_participation_year == year

# GEN-AREA-RED-001: Toleranz für Flächenverringerungen: bis 5 % des Vorjahres, höchstens 5 ha,
# jedenfalls 0,50 ha pro Jahr.
area_reduction_tolerance_ha(previous_ha) := max([
	params.area_reduction_tolerance.always_allowed_ha_per_year,
	min([previous_ha * params.area_reduction_tolerance.max_share_of_previous_year, params.area_reduction_tolerance.max_ha_per_year]),
])

# Rückzahlungspflichtige Differenzfläche (gesamte Differenz bei Überschreitung, sonst 0).
# exempt_ha: Verlust der Verfügungsgewalt bzw. jedenfalls zulässige Umwandlungen.
area_reduction_repayment_ha(previous_ha, current_ha, exempt_ha) := d if {
	d := (previous_ha - current_ha) - exempt_ha
	d > area_reduction_tolerance_ha(previous_ha)
} else := 0

# GEN-AREA-ADD-001: Flächenzugänge 2024 und 2025 zur Gänze prämienfähig; danach max. +50 %
# auf Basis 2025, eine Vergrößerung um bis zu 5 ha jedenfalls zulässig.
premium_eligible_area_limit_ha(area_2025_ha, yr) := l if {
	not yr in {y | some y in params.area_addition_limits.fully_eligible_years}
	yr > params.area_addition_limits.base_year
	l := area_2025_ha + max([
		area_2025_ha * params.area_addition_limits.max_increase_share_of_base,
		params.area_addition_limits.increase_always_allowed_ha,
	])
}

area_addition_excess_ha(current_ha, area_2025_ha, yr) := max([0, current_ha - premium_eligible_area_limit_ha(area_2025_ha, yr)]) if {
	yr > params.area_addition_limits.base_year
} else := 0

# GEN-SANC-001: Sanktionsstufen; ab 2027 statt Verwarnung Einbehalt von 1 %.
sanction_reduction_percent(stage, yr) := s.retention_percent_from_2027 if {
	some s in params.sanction_stages.rows
	s.stage == stage
	s.type == "warning"
	yr >= params.sanction_stages.warning_replaced_by_retention_from_year
} else := s.reduction_percent if {
	some s in params.sanction_stages.rows
	s.stage == stage
}

# Ausschluss bei zweimaliger 100 %-Kürzung im Vertragszeitraum.
excluded_from_measure if {
	object.get(measure_record, "full_reductions_100pct_count", 0) >= params.sanction_stages.exclusion_after_full_reductions
}

# SRL-SANC-ACCESS-001: Nichterfüllung von Zugangsvoraussetzungen bei mehrjährigen Maßnahmen.
access_failure_consequence(commitment_year) := "no_contract" if {
	commitment_year == 1
} else := "no_premium_in_year"

# GEN-DUR-002: unterjährige Flächenweitergabe ohne Weiterführung bis Jahresende → keine Prämie (Code OP).
violation contains {"rule_id": "GEN-DUR-002", "parcel_id": pid, "message": "Fläche unterjährig weitergegeben ohne Weiterführung der Verpflichtung – Code OP erforderlich"} if {
	some pid, p in enrolled_parcels
	object.get(p, "transferred_mid_year_without_continuation", false) == true
	not "OP" in object.get(p, "oepul_codes", [])
}

# SRL-FM-002: dauerhafte flächen-/bewirtschaftungsverändernde Umstände – Prämie im Eintrittsjahr nur,
# wenn Eintritt nach dem 15.04. (bzw. höhere Gewalt/außergewöhnliche Umstände).
premium_in_year_of_permanent_circumstance(_, force_majeure) if force_majeure == true

premium_in_year_of_permanent_circumstance(event_date, _) if {
	yr := date_parts(event_date)[0]
	date_ns(event_date) > date_ns(sprintf("%d-04-15", [yr]))
}

# O6_4-XM-001/-002/-003: Bergmähder zählen nicht zur gemähten Grünlandbezugsfläche anderer Maßnahmen
# (UBB/BIO-Biodiversitätsflächen, Heuwirtschaft-Mindestfläche, Zuschlag artenreiches Grünland).
grassland_basis_excluding_mountain_meadows_ha := sum([p.area_ha |
	some p in input.land.parcels
	p.land_use == "grassland"
	not object.get(p, ["mountain_meadow", "declared_as_mountain_meadow"], false) == true
])

# Förderbedingungen (Maßnahmenblatt Kap. 4, 5.1; SRL 2.4 Förderverpflichtungen).
# Die Auflagen gelten auf allen Maßnahmenflächen, auch in Jahren mit Codierung BM0.
package oepul.o6_4

# O6_4-MOW-001: zumindest jedes zweite Jahr vollflächige Mahd inkl. Verbringung des Mähgutes.
violation contains {"rule_id": "O6_4-MOW-001", "parcel_id": pid, "message": "keine vollflächige Mahd mit Verbringung im laufenden Jahr und keine Mahd im Vorjahr"} if {
	some pid, p in enrolled_parcels
	not valid_full_mowing_this_year(p)
	not mowed_previous_year(p)
}

# O6_4-MOW-002: maximal eine Mahd pro Jahr.
violation contains {"rule_id": "O6_4-MOW-002", "parcel_id": pid, "message": sprintf("%d Mahden im Jahr – maximal eine Mahd zulässig", [mowing_count(p)])} if {
	some pid, p in enrolled_parcels
	mowing_count(p) > 1
}

# O6_4-MOW-003: Mähen und Liegenlassen des Erntegutes oder Häckseln ist nicht zulässig.
violation contains {"rule_id": "O6_4-MOW-003", "parcel_id": pid, "message": "Fläche gehäckselt – nicht zulässig"} if {
	some pid, p in enrolled_parcels
	mowing_info(p).mulched == true
}

violation contains {"rule_id": "O6_4-MOW-003", "parcel_id": pid, "message": "Mähgut nicht von der Fläche verbracht – nicht zulässig"} if {
	some pid, p in enrolled_parcels
	mowed_this_year(p)
	mown_material_not_removed(p)
}

mown_material_not_removed(p) if mowing_info(p).mown_material_left_lying == true

mown_material_not_removed(p) if mowing_info(p).mown_material_removed == false

# O6_4-GRAZE-001: grundsätzlich keine Beweidung; Nachweide ab 16. August jährlich zulässig.
violation contains {"rule_id": "O6_4-GRAZE-001", "parcel_id": pid, "message": sprintf("Beweidung am %s vor dem 16. August", [d])} if {
	some pid, p in enrolled_parcels
	some d in object.get(p, ["operations", "grazing_dates"], [])
	date_parts(d)[0] == year
	before_month_day(d, 8, 16)
}

# O6_4-FERT-001/-002/-003: Verzicht auf Düngemittel, Klärschlamm und kompostierten Klärschlamm;
# ausgenommen Festmist in ursprünglicher Form und eigene häusliche Abwässer.
allowed_fertilizer_types := {f.type | some f in data.o6_4.input_substances.fertilizer_types; f.allowed}

violation contains {"rule_id": "O6_4-FERT-001", "parcel_id": pid, "message": sprintf("unzulässige Ausbringung: %s", [t])} if {
	some pid, p in enrolled_parcels
	some t in object.get(p, ["operations", "fertilizer", "applied_types"], [])
	not t in allowed_fertilizer_types
}

violation contains {"rule_id": "O6_4-FERT-001", "parcel_id": pid, "message": "mineralische Stickstoffdüngung angegeben"} if {
	some pid, p in enrolled_parcels
	object.get(p, ["operations", "fertilizer", "mineral_n_kg_per_ha"], 0) > 0
}

# O6_4-PSM-001: keine Pflanzenschutzmittel außer solchen mit ausschließlich gemäß VO (EU) 2018/848 zulässigen Wirkstoffen.
violation contains {"rule_id": "O6_4-PSM-001", "parcel_id": pid, "message": "Pflanzenschutzmittel ohne ausschließlich bio-zulässige Wirkstoffe eingesetzt"} if {
	some pid, p in enrolled_parcels
	object.get(p, ["operations", "psm_used"], false) == true
	not object.get(p, ["operations", "psm_only_bio_approved_substances"], false) == true
}

# O6_4-CODE-002/-004: Codierung BM1/BM2/BM3 im Jahr der Mahd je nach Mähverfahren, BM0 ohne Mahd.
violation contains {"rule_id": "O6_4-CODE-002", "parcel_id": pid, "message": "kein eindeutiger Code BM0/BM1/BM2/BM3 angegeben"} if {
	some pid, p in enrolled_parcels
	count(parcel_bm_codes(p)) != 1
}

violation contains {"rule_id": "O6_4-CODE-004", "parcel_id": pid, "message": "Mahd durchgeführt, aber mit BM0 codiert"} if {
	some pid, p in enrolled_parcels
	parcel_bm_code(p) == "BM0"
	mowed_this_year(p)
}

violation contains {"rule_id": "O6_4-CODE-004", "parcel_id": pid, "message": sprintf("Code %s angegeben, aber keine Mahd im Jahr", [parcel_bm_code(p)])} if {
	some pid, p in enrolled_parcels
	parcel_bm_code(p) in mowing_year_codes
	not mowed_this_year(p)
}

# O6_4-CODE-003: Code richtet sich nach dem (überwiegenden) Mähverfahren; Ausmähen mit der Sense ändert ihn nicht.
violation contains {"rule_id": "O6_4-CODE-003", "parcel_id": pid, "message": sprintf("Code %s passt nicht zum Mähverfahren %s", [code, method])} if {
	some pid, p in enrolled_parcels
	code := parcel_bm_code(p)
	code in mowing_year_codes
	method := mowing_info(p).method
	method != code_method(code)
}

# Codierung, die dem tatsächlichen Mähverfahren entspricht.
expected_code_for_method(method) := c.code if {
	some c in data.o6_4.mowing_codes.codes
	c.mowing_method == method
}

# Höhe der Prämie, Kombinationen, Obergrenzen und Modulation
# (Maßnahmenblatt Kap. 6; SRL 2.4 Höhe der Förderung, 1.9; Anhang L; Allgemeine Bedingungen 9.2, 9.3).
package oepul.o6_4

# O6_4-PREM-001: Prämiensatz je Code und Antragsjahr aus der Prämientabelle.
premium_rate(code, yr) := r.eur_per_ha if {
	some r in data.o6_4.premium_rates.rows
	r.code == code
	r.valid_from_year <= yr
	year_within_upper(r.valid_to_year, yr)
}

year_within_upper(upper, _) if upper == null

year_within_upper(upper, yr) if {
	upper != null
	yr <= upper
}

# GEN-OP-001 / GEN-VF-001: Codes OP bzw. VF – keine Prämie im jeweiligen Jahr.
no_premium_code(p) if {
	some c in object.get(p, "oepul_codes", [])
	c in {x | some x in params.op_code_mandatory_cases.no_premium_codes}
}

# GEN-NP-001: Flächen in Nationalparks erhalten in o6_4 keine Prämie
# (außer es sind keine relevanten Bewirtschaftungsauflagen festgelegt).
national_park_no_premium(p) if {
	object.get(p, ["constraints", "in_national_park"], false) == true
	not object.get(p, ["constraints", "national_park_without_relevant_restrictions"], false) == true
}

# O6_4-PREM-002: Prämiengewährung nur im Jahr der Mahd (BM1–BM3 mit tatsächlicher vollflächiger Mahd).
premium_parcel_reason(pid) := "not_eligible" if {
	enrolled_parcels[pid]
	not parcel_eligible(pid)
} else := "no_unique_code" if {
	not parcel_bm_code(enrolled_parcels[pid])
} else := "no_mowing" if {
	not parcel_bm_code(enrolled_parcels[pid]) in mowing_year_codes
} else := "no_valid_full_mowing" if {
	not valid_full_mowing_this_year(enrolled_parcels[pid])
} else := "op_or_vf_code" if {
	no_premium_code(enrolled_parcels[pid])
} else := "national_park" if {
	national_park_no_premium(enrolled_parcels[pid])
} else := "rate_missing" if {
	not premium_rate(parcel_bm_code(enrolled_parcels[pid]), year)
} else := "premium"

parcel_premium[pid] := round_cent(p.area_ha * premium_rate(parcel_bm_code(p), year)) if {
	some pid, p in enrolled_parcels
	premium_parcel_reason(pid) == "premium"
}

parcel_premium[pid] := 0 if {
	some pid, _ in enrolled_parcels
	premium_parcel_reason(pid) != "premium"
}

round_cent(x) := round(x * 100) / 100

premium_before_modulation := round_cent(sum([v | some v in parcel_premium]))

# O6_4-PREM-003 / GEN-COMB-001: auf der Einzelfläche mit keiner anderen ÖPUL-Maßnahme kombinierbar,
# ausgenommen Abgeltung (punktförmiger) Landschaftselemente in 1A/1B (Anhang L, Fußnote 1).
combination_row := r if {
	some r in data.o6_4.combination_table.rows
	r.measure_id == "4"
}

combination_cell(other_id) := c if {
	some c in combination_row.cells
	c.measure_id == other_id
}

combination_permitted(other_id, component) if {
	cell := combination_cell(other_id)
	cell.marker != null
	not "1" in cell.footnotes
	component != null
}

combination_permitted(other_id, component) if {
	cell := combination_cell(other_id)
	cell.marker != null
	"1" in cell.footnotes
	component == "landscape_element"
}

# Zuordnung Maßnahmen-ID (o6_x) → Spaltenkennung Anhang L.
annex_l_id(mid) := upper(trim_prefix(mid, "o6_"))

combination_conflict contains {"rule_id": "O6_4-PREM-003", "parcel_id": pid, "other_measure": m.measure_id, "premium_component": object.get(m, "premium_component", "area")} if {
	some pid, p in enrolled_parcels
	some m in object.get(p, "oepul_measure_participation", [])
	m.measure_id != measure_id
	not combination_permitted(annex_l_id(m.measure_id), object.get(m, "premium_component", "area"))
}

# GEN-CAP-001: Prämienobergrenze je ha für die Summe flächenbezogener Zahlungen inkl. Landschaftselemente.
premium_cap_per_ha(cap_type, yr) := r.eur_per_ha if {
	some r in params.premium_caps.rows
	r.cap_type == cap_type
	r.year_from <= yr
	year_within_upper(r.year_to, yr)
}

parcel_payment_per_ha(pid) := total if {
	p := enrolled_parcels[pid]
	own := premium_rate(parcel_bm_code(p), year)
	others := sum([v |
		some m in object.get(p, "oepul_measure_participation", [])
		m.measure_id != measure_id
		v := object.get(m, "payment_eur_per_ha", 0)
	])
	total := own + others
}

cap_exceeded contains {"rule_id": "GEN-CAP-001", "parcel_id": pid, "payment_eur_per_ha": v, "cap_eur_per_ha": cap} if {
	some pid, _ in enrolled_parcels
	premium_parcel_reason(pid) == "premium"
	v := parcel_payment_per_ha(pid)
	cap := premium_cap_per_ha("general", year)
	v > cap
}

# GEN-MOD-001: Betriebsgrößenmodulation (gestaffelter Auszahlungsfaktor nach Gesamtfläche).
modulation_factor(total_ha) := 1 if total_ha <= 0

modulation_factor(total_ha) := f if {
	total_ha > 0
	weighted := [v |
		some t in params.modulation_tiers.rows
		v := tier_share(t, total_ha) * t.payout_factor
	]
	f := sum(weighted) / total_ha
}

tier_share(t, total_ha) := max([0, min([tier_upper(t, total_ha), total_ha]) - t.from_ha_exclusive])

tier_upper(t, total_ha) := total_ha if t.to_ha_inclusive == null

tier_upper(t, _) := t.to_ha_inclusive if t.to_ha_inclusive != null

default farm_total_area_ha := 0

farm_total_area_ha := input.land.total_area_ha

premium_after_modulation := round_cent(premium_before_modulation * modulation_factor(farm_total_area_ha))

# GEN-PAY-002: Von der Gewährung kann abgesehen werden, wenn der Auszahlungsbetrag 50 Euro nicht überschreitet.
payment_may_be_waived(amount) if amount <= params.payment.min_payout_eur_exclusive

# GEN-PAY-001: Teilzahlung höchstens 75 % nach Abschluss der Verwaltungskontrollen.
max_advance_payment(amount) := round_cent(amount * params.payment.max_advance_share)

